﻿using Bit.Identity.IdentityServer;
using Duende.IdentityServer.Models;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using NSubstitute;
using Xunit;

namespace Bit.Identity.Test.IdentityServer;

public class DynamicClientStoreTests
{
    private readonly IServiceCollection _services;
    private readonly IClientProvider _apiKeyProvider;

    private readonly Func<DynamicClientStore> _sutCreator;

    public DynamicClientStoreTests()
    {
        _services = new ServiceCollection();
        _apiKeyProvider = Substitute.For<IClientProvider>();

        _sutCreator = () => new DynamicClientStore(
            _services.BuildServiceProvider(),
            _apiKeyProvider,
            new StaticClientStore(new Core.Settings.GlobalSettings(), NullLogger<StaticClientStore>.Instance)
        );
    }

    [Theory]
    [InlineData("mobile")]
    [InlineData("web")]
    [InlineData("browser")]
    [InlineData("desktop")]
    [InlineData("cli")]
    [InlineData("connector")]
    public async Task FindClientByIdAsync_StaticClients_Works(string staticClientId)
    {
        var sut = _sutCreator();

        var client = await sut.FindClientByIdAsync(staticClientId);

        Assert.NotNull(client);
        Assert.Equal(staticClientId, client.ClientId);
    }

    [Fact]
    public async Task FindClientByIdAsync_SplitName_NoService_ReturnsNull()
    {
        _services.AddClientProvider<FakeClientProvider>("my-provider");

        var sut = _sutCreator();

        var client = await sut.FindClientByIdAsync("blah.something");

        Assert.Null(client);

        await _apiKeyProvider
            .Received(0)
            .GetAsync(Arg.Any<string>());
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public async Task FindClientByIdAsync_SplitName_HasService_ReturnsValueFromService(bool returnNull)
    {
        var fakeProvider = Substitute.For<IClientProvider>();

        fakeProvider
            .GetAsync("something")
            .Returns(returnNull ? null : new Client { ClientId = "fake" });

        _services.AddKeyedSingleton("my-provider", fakeProvider);

        var sut = _sutCreator();

        var client = await sut.FindClientByIdAsync("my-provider.something");

        if (returnNull)
        {
            Assert.Null(client);
        }
        else
        {
            Assert.NotNull(client);
        }

        await fakeProvider
            .Received(1)
            .GetAsync("something");

        await _apiKeyProvider
            .Received(0)
            .GetAsync(Arg.Any<string>());
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public async Task FindClientByIdAsync_RandomString_NotSplit_TriesApiKey(bool returnsNull)
    {
        _apiKeyProvider
            .GetAsync("random-string")
            .Returns(returnsNull ? null : new Client { ClientId = "test" });

        var sut = _sutCreator();

        var client = await sut.FindClientByIdAsync("random-string");

        if (returnsNull)
        {
            Assert.Null(client);
        }
        else
        {
            Assert.NotNull(client);
        }

        await _apiKeyProvider
            .Received(1)
            .GetAsync("random-string");
    }

    [Theory]
    [InlineData("id.")]
    [InlineData("id.    ")]
    public async Task FindClientByIdAsync_InvalidIdentifierValue_ReturnsNull(string clientId)
    {
        var sut = _sutCreator();

        var client = await sut.FindClientByIdAsync(clientId);
        Assert.Null(client);
    }

    private class FakeClientProvider : IClientProvider
    {
        public FakeClientProvider()
        {
            Fake = Substitute.For<IClientProvider>();
        }

        public IClientProvider Fake { get; }

        public Task<Client?> GetAsync(string identifier)
        {
            return Fake.GetAsync(identifier);
        }
    }
}

﻿using Bit.Core;
using Bit.Core.Enums;
using Bit.Core.Settings;
using Bit.Identity.IdentityServer;
using Bit.Identity.Utilities;
using Duende.IdentityServer.Models;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using NSubstitute;
using Xunit;

namespace Bit.Identity.Test.IdentityServer;

public class StaticClientStoreTests
{
    private const string TestVaultUri = "https://vault.example.com";

    private static readonly string[] InteractiveClients =
    {
        BitwardenClient.Mobile,
        BitwardenClient.Web,
        BitwardenClient.Browser,
        BitwardenClient.Desktop,
        BitwardenClient.Cli,
        BitwardenClient.DirectoryConnector,
    };

    private static GlobalSettings NewSettings()
    {
        var s = new GlobalSettings();
        s.BaseServiceUri.Vault = TestVaultUri;
        return s;
    }

    private static StaticClientStore Build(GlobalSettings globalSettings, ILogger<StaticClientStore>? logger = null)
    {
        return new StaticClientStore(globalSettings, logger ?? NullLogger<StaticClientStore>.Instance);
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile, 3600)]
    [InlineData(BitwardenClient.Web, 3600)]
    [InlineData(BitwardenClient.Browser, 3600)]
    [InlineData(BitwardenClient.Desktop, 3600)]
    [InlineData(BitwardenClient.Cli, 3600)]
    [InlineData(BitwardenClient.DirectoryConnector, 24 * 3600)]
    public void AccessTokenLifetime_MatchesHardcodedDefault(string clientId, int expectedSeconds)
    {
        var sut = Build(NewSettings());

        Assert.Equal(expectedSeconds, sut.Clients[clientId].AccessTokenLifetime);
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile, 60 * 86400)]
    [InlineData(BitwardenClient.Web, 7 * 86400)]
    [InlineData(BitwardenClient.Browser, 30 * 86400)]
    [InlineData(BitwardenClient.Desktop, 30 * 86400)]
    [InlineData(BitwardenClient.Cli, 30 * 86400)]
    [InlineData(BitwardenClient.DirectoryConnector, 30 * 86400)]
    public void SlidingRefreshTokenLifetime_DerivedFromPerClientDays_WhenNoOverride(string clientId, int expectedSeconds)
    {
        var sut = Build(NewSettings());

        Assert.Equal(expectedSeconds, sut.Clients[clientId].SlidingRefreshTokenLifetime);
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile)]
    [InlineData(BitwardenClient.Web)]
    [InlineData(BitwardenClient.Browser)]
    [InlineData(BitwardenClient.Desktop)]
    [InlineData(BitwardenClient.Cli)]
    [InlineData(BitwardenClient.DirectoryConnector)]
    public void SlidingRefreshTokenLifetime_UsesGlobalOverride_WhenSet(string clientId)
    {
        var settings = NewSettings();
        settings.IdentityServer.SlidingRefreshTokenLifetimeSeconds = 12345;

        var sut = Build(settings);

        Assert.Equal(12345, sut.Clients[clientId].SlidingRefreshTokenLifetime);
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile)]
    [InlineData(BitwardenClient.Web)]
    [InlineData(BitwardenClient.Browser)]
    [InlineData(BitwardenClient.Desktop)]
    [InlineData(BitwardenClient.Cli)]
    [InlineData(BitwardenClient.DirectoryConnector)]
    public void AbsoluteRefreshTokenLifetime_DefaultsToZero(string clientId)
    {
        var sut = Build(NewSettings());

        Assert.Equal(0, sut.Clients[clientId].AbsoluteRefreshTokenLifetime);
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile)]
    [InlineData(BitwardenClient.Web)]
    [InlineData(BitwardenClient.Browser)]
    [InlineData(BitwardenClient.Desktop)]
    [InlineData(BitwardenClient.Cli)]
    [InlineData(BitwardenClient.DirectoryConnector)]
    public void AbsoluteRefreshTokenLifetime_UsesGlobalOverride_WhenSet(string clientId)
    {
        var settings = NewSettings();
        settings.IdentityServer.AbsoluteRefreshTokenLifetimeSeconds = 99999;

        var sut = Build(settings);

        Assert.Equal(99999, sut.Clients[clientId].AbsoluteRefreshTokenLifetime);
    }

    [Theory]
    [InlineData(false, TokenExpiration.Sliding)]
    [InlineData(true, TokenExpiration.Absolute)]
    public void RefreshTokenExpiration_DerivedFromApplyAbsoluteFlag(bool absoluteFlag, TokenExpiration expected)
    {
        var settings = NewSettings();
        settings.IdentityServer.ApplyAbsoluteExpirationOnRefreshToken = [REDACTED];

        var sut = Build(settings);

        foreach (var id in InteractiveClients)
        {
            Assert.Equal(expected, sut.Clients[id].RefreshTokenExpiration);
        }
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile)]
    [InlineData(BitwardenClient.Web)]
    [InlineData(BitwardenClient.Browser)]
    [InlineData(BitwardenClient.Desktop)]
    [InlineData(BitwardenClient.Cli)]
    [InlineData(BitwardenClient.DirectoryConnector)]
    public void SharedClientDefaults_AreSetIdenticallyForAllInteractiveClients(string clientId)
    {
        var client = Build(NewSettings()).Clients[clientId];

        Assert.Equal(clientId, client.ClientId);
        Assert.Equal(TokenUsage.ReUse, client.RefreshTokenUsage);
        Assert.True(client.UpdateAccessTokenClaimsOnRefresh);
        Assert.True(client.AllowOfflineAccess);
        Assert.False(client.RequireConsent);
        Assert.True(client.RequirePkce);
        Assert.False(client.RequireClientSecret);
        Assert.Equal(new[] { "api" }, client.AllowedScopes);
        Assert.Contains("password", client.AllowedGrantTypes);
        Assert.Contains("authorization_code", client.AllowedGrantTypes);
        Assert.Contains("webauthn", client.AllowedGrantTypes);
    }

    [Theory]
    [InlineData(BitwardenClient.Web)]
    [InlineData(BitwardenClient.Browser)]
    public void WebAndBrowser_RedirectAndCorsUris_UseVaultUri(string clientId)
    {
        var client = Build(NewSettings()).Clients[clientId];

        Assert.Equal(new[] { $"{TestVaultUri}/sso-connector.html" }, client.RedirectUris);
        Assert.Equal(new[] { TestVaultUri }, client.PostLogoutRedirectUris);
        Assert.Equal(new[] { TestVaultUri }, client.AllowedCorsOrigins);
    }

    [Fact]
    public void Desktop_RedirectUris_IncludeSchemeCallbackAndLocalhostPorts()
    {
        var client = Build(NewSettings()).Clients[BitwardenClient.Desktop];

        Assert.Contains("bitwarden://sso-callback", client.RedirectUris);
        foreach (var port in Enumerable.Range(8065, 6))
        {
            Assert.Contains($"http://localhost:{port}", client.RedirectUris);
        }
        Assert.Equal(new[] { "bitwarden://logged-out" }, client.PostLogoutRedirectUris);
        Assert.Empty(client.AllowedCorsOrigins);
    }

    [Fact]
    public void DirectoryConnector_RedirectUris_IncludeLocalhostPortsAndBwdcCallback()
    {
        var client = Build(NewSettings()).Clients[BitwardenClient.DirectoryConnector];

        foreach (var port in Enumerable.Range(8065, 6))
        {
            Assert.Contains($"http://localhost:{port}", client.RedirectUris);
            Assert.Contains($"http://localhost:{port}", client.PostLogoutRedirectUris);
        }
        Assert.Contains("bwdc://sso-callback", client.RedirectUris);
        Assert.Contains("bwdc://logged-out", client.PostLogoutRedirectUris);
        Assert.Empty(client.AllowedCorsOrigins);
    }

    [Fact]
    public void Cli_RedirectAndPostLogoutUris_AreLocalhostPortsOnly()
    {
        var client = Build(NewSettings()).Clients[BitwardenClient.Cli];

        var expected = Enumerable.Range(8065, 6).Select(p => $"http://localhost:{p}").ToArray();
        Assert.Equal(expected, client.RedirectUris);
        Assert.Equal(expected, client.PostLogoutRedirectUris);
        Assert.Empty(client.AllowedCorsOrigins);
    }

    [Fact]
    public void Mobile_RedirectUris_UseMobileSsoConstants()
    {
        var client = Build(NewSettings()).Clients[BitwardenClient.Mobile];

        Assert.Equal(Constants.BitwardenMobileSsoCallbackUris, client.RedirectUris);
        Assert.Equal(new[] { "bitwarden://logged-out" }, client.PostLogoutRedirectUris);
        Assert.Empty(client.AllowedCorsOrigins);
    }

    [Fact]
    public void Clients_IncludesSendClient()
    {
        var sut = Build(NewSettings());

        Assert.True(sut.Clients.ContainsKey(BitwardenClient.Send));
    }

    [Theory]
    [InlineData(BitwardenClient.Mobile)]
    [InlineData(BitwardenClient.Web)]
    [InlineData(BitwardenClient.Browser)]
    [InlineData(BitwardenClient.Desktop)]
    [InlineData(BitwardenClient.Cli)]
    public void Override_AppliesToInteractiveClients(string clientId)
    {
        var settings = NewSettings();
        settings.IdentityServer.AccessTokenLifetimeSeconds = 900;

        var sut = Build(settings);

        Assert.Equal(900, sut.Clients[clientId].AccessTokenLifetime);
    }

    [Fact]
    public void Override_DoesNotAffectDirectoryConnector()
    {
        var settings = NewSettings();
        settings.IdentityServer.AccessTokenLifetimeSeconds = 900;

        var sut = Build(settings);

        Assert.Equal(24 * 3600, sut.Clients[BitwardenClient.DirectoryConnector].AccessTokenLifetime);
    }

    [Theory]
    [InlineData(60)]
    [InlineData(300)]
    [InlineData(599)]
    public void Override_BelowRecommendedMinimum_LogsWarning(int seconds)
    {
        var logger = Substitute.For<ILogger<StaticClientStore>>();
        logger.IsEnabled(Arg.Any<LogLevel>()).Returns(true);

        var settings = NewSettings();
        settings.IdentityServer.AccessTokenLifetimeSeconds = seconds;

        Build(settings, logger);

        logger.Received().Log(
            LogLevel.Warning,
            Arg.Any<EventId>(),
            Arg.Is<object>(o => o.ToString()!.Contains("refresh threshold")),
            Arg.Any<Exception?>(),
            Arg.Any<Func<object, Exception?, string>>()!);
    }

    [Theory]
    [InlineData(600)]
    [InlineData(900)]
    [InlineData(3600)]
    public void Override_AtOrAboveRecommendedMinimum_DoesNotWarn(int seconds)
    {
        var logger = Substitute.For<ILogger<StaticClientStore>>();
        logger.IsEnabled(Arg.Any<LogLevel>()).Returns(true);

        var settings = NewSettings();
        settings.IdentityServer.AccessTokenLifetimeSeconds = seconds;

        Build(settings, logger);

        logger.DidNotReceive().Log(
            LogLevel.Warning,
            Arg.Any<EventId>(),
            Arg.Any<object>(),
            Arg.Any<Exception?>(),
            Arg.Any<Func<object, Exception?, string>>()!);
    }

    [Theory]
    [InlineData(0)]
    [InlineData(-1)]
    public void StartupValidation_RejectsNonPositiveOverride(int badValue)
    {
        var settings = NewSettings();
        settings.IdentityServer.AccessTokenLifetimeSeconds = badValue;

        var ex = Assert.Throws<InvalidOperationException>(
            () => ServiceCollectionExtensions.ValidateAccessTokenLifetimeOverride(settings));

        Assert.Contains("accessTokenLifetimeSeconds", ex.Message);
    }

    [Fact]
    public void StartupValidation_AllowsPositiveOverride()
    {
        var settings = NewSettings();
        settings.IdentityServer.AccessTokenLifetimeSeconds = 60;

        ServiceCollectionExtensions.ValidateAccessTokenLifetimeOverride(settings);
    }

    [Fact]
    public void StartupValidation_AllowsNull()
    {
        ServiceCollectionExtensions.ValidateAccessTokenLifetimeOverride(NewSettings());
    }
}

﻿using Bit.Core.Settings;
using Duende.IdentityServer;
using Duende.IdentityServer.Models;

namespace Bit.Sso.IdentityServer;

public class OidcIdentityClient : Client
{
    public OidcIdentityClient(GlobalSettings globalSettings)
    {
        ClientId = "oidc-identity";
        RequireClientSecret = true;
        RequirePkce = true;
        ClientSecrets = new List<Secret> { new(globalSettings.OidcIdentityClientKey.Sha256()) };
        AllowedScopes = new[]
        {
            IdentityServerConstants.StandardScopes.OpenId,
            IdentityServerConstants.StandardScopes.Profile
        };
        AllowedGrantTypes = GrantTypes.Code;
        Enabled = true;
        RedirectUris = new List<string> { $"{globalSettings.BaseServiceUri.Identity}/signin-oidc" };
        RequireConsent = false;
    }
}

﻿using Bit.Core.AdminConsole.Entities;
using Bit.Core.AdminConsole.Models.OrganizationConnectionConfigs;
using Bit.Core.Entities;
using Bit.Core.Enums;
using Bit.Core.Repositories;
using Bit.Scim.Context;
using Bit.Scim.Utilities;
using Bit.Test.Common.AutoFixture;
using Bit.Test.Common.AutoFixture.Attributes;
using Duende.IdentityModel;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using NSubstitute;
using Xunit;

namespace Bit.Scim.Test.Utilities;

[SutProviderCustomize]
public class ApiKeyAuthenticationHandlerTests
{
    [Theory]
    [BitAutoData]
    public async Task HandleAuthenticate_ValidApiKey_Succeeds(SutProvider<ApiKeyAuthenticationHandler> sutProvider, Organization organization, string apiKey)
    {
        ArrangeScimEnabledOrganization(sutProvider, organization, apiKey);

        var result = await AuthenticateAsync(sutProvider, $"Bearer {apiKey}");

        Assert.True(result.Succeeded);
        Assert.Equal($"organization.{organization.Id}",
            result.Principal.FindFirst(JwtClaimTypes.ClientId)?.Value);
        Assert.Equal(organization.Id.ToString(), result.Principal.FindFirst("client_sub")?.Value);
        Assert.Equal("api.scim", result.Principal.FindFirst(JwtClaimTypes.Scope)?.Value);
    }

    [Theory]
    [BitAutoData]
    public async Task HandleAuthenticate_InvalidApiKey_FailsWithoutLoggingSubmittedKey(
        SutProvider<ApiKeyAuthenticationHandler> sutProvider, Organization organization, string apiKey)
    {
        var logger = ArrangeScimEnabledOrganization(sutProvider, organization, apiKey);
        var submittedKey = apiKey + "-wrong";

        var result = await AuthenticateAsync(sutProvider, $"Bearer {submittedKey}");

        Assert.False(result.Succeeded);
        logger.DidNotReceive().Log(
            Arg.Any<LogLevel>(),
            Arg.Any<EventId>(),
            Arg.Is<object>(state => state.ToString().Contains(submittedKey)),
            Arg.Any<Exception>(),
            Arg.Any<Func<object, Exception, string>>());
    }

    [Theory]
    [BitAutoData]
    public async Task HandleAuthenticate_NoMatchingApiKey_Fails(
        SutProvider<ApiKeyAuthenticationHandler> sutProvider, Organization organization, string apiKey)
    {
        ArrangeScimEnabledOrganization(sutProvider, organization, apiKey);
        sutProvider.GetDependency<IOrganizationApiKeyRepository>()
            .GetManyByOrganizationIdTypeAsync(organization.Id, OrganizationApiKeyType.Scim)
            .Returns([]);

        var result = await AuthenticateAsync(sutProvider, $"Bearer {apiKey}");

        Assert.False(result.Succeeded);
    }

    [Theory]
    [BitAutoData]
    public async Task HandleAuthenticate_NoOrganization_Fails(SutProvider<ApiKeyAuthenticationHandler> sutProvider)
    {
        ArrangeLogger(sutProvider);

        sutProvider.GetDependency<IScimContext>().OrganizationId.Returns((Guid?)null);
        sutProvider.GetDependency<IScimContext>().Organization.Returns((Organization)null);

        var result = await AuthenticateAsync(sutProvider, "Bearer anything");

        Assert.False(result.Succeeded);
    }

    [Theory]
    [BitAutoData]
    public async Task HandleAuthenticate_MissingAuthorizationHeader_Fails(SutProvider<ApiKeyAuthenticationHandler> sutProvider, Organization organization, string apiKey)
    {
        ArrangeScimEnabledOrganization(sutProvider, organization, apiKey);

        var result = await AuthenticateAsync(sutProvider, authorizationHeader: null);

        Assert.False(result.Succeeded);
    }

    [Theory]
    [BitAutoData]
    public async Task HandleAuthenticate_OrganizationCannotUseScim_Fails(SutProvider<ApiKeyAuthenticationHandler> sutProvider, Organization organization, string apiKey)
    {
        organization.Enabled = true;
        organization.UseScim = false;

        ArrangeLogger(sutProvider);

        var scimContext = sutProvider.GetDependency<IScimContext>();
        scimContext.OrganizationId.Returns(organization.Id);
        scimContext.Organization.Returns(organization);
        scimContext.ScimConfiguration.Returns(new ScimConfig { Enabled = true });

        var result = await AuthenticateAsync(sutProvider, $"Bearer {apiKey}");

        Assert.False(result.Succeeded);
    }

    private static ILogger ArrangeLogger(SutProvider<ApiKeyAuthenticationHandler> sutProvider)
    {
        var logger = Substitute.For<ILogger>();
        sutProvider.GetDependency<ILoggerFactory>().CreateLogger(Arg.Any<string>()).Returns(logger);
        return logger;
    }

    private static ILogger ArrangeScimEnabledOrganization(SutProvider<ApiKeyAuthenticationHandler> sutProvider, Organization organization, string apiKey)
    {
        var logger = ArrangeLogger(sutProvider);

        organization.Enabled = true;
        organization.UseScim = true;

        var scimContext = sutProvider.GetDependency<IScimContext>();
        scimContext.OrganizationId.Returns(organization.Id);
        scimContext.Organization.Returns(organization);
        scimContext.ScimConfiguration.Returns(new ScimConfig { Enabled = true });

        sutProvider.GetDependency<IOrganizationApiKeyRepository>()
            .GetManyByOrganizationIdTypeAsync(organization.Id, OrganizationApiKeyType.Scim)
            .Returns([new OrganizationApiKey { OrganizationId = organization.Id, Type = OrganizationApiKeyType.Scim, ApiKey = apiKey }
            ]);

        return logger;
    }

    private static async Task<AuthenticateResult> AuthenticateAsync(SutProvider<ApiKeyAuthenticationHandler> sutProvider, string? authorizationHeader)
    {
        sutProvider.GetDependency<IOptionsMonitor<ApiKeyAuthenticationOptions>>()
            .Get(Arg.Any<string>())
            .Returns(new ApiKeyAuthenticationOptions());

        var httpContext = new DefaultHttpContext();
        if (authorizationHeader is not null)
        {
            httpContext.Request.Headers.Authorization = [REDACTED];
        }

        var scheme = new AuthenticationScheme(
            ApiKeyAuthenticationOptions.DefaultScheme, null, typeof(ApiKeyAuthenticationHandler));
        await sutProvider.Sut.InitializeAsync(scheme, httpContext);

        return await sutProvider.Sut.AuthenticateAsync();
    }
}

