﻿using System.Diagnostics;
using System.Globalization;
using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Bit.Core.Utilities;
using Microsoft.Extensions.Logging;

namespace Bit.Core.Services;

public abstract class BaseIdentityClientService : IDisposable
{
    private readonly IHttpClientFactory _httpFactory;
    private readonly string _identityScope;
    private readonly string _identityClientId;
    private readonly string _identityClientSecret;
    protected readonly ILogger<BaseIdentityClientService> _logger;

    private JsonDocument? _decodedToken;
    private DateTime? _nextAuthAttempt = null;

    public BaseIdentityClientService(
        IHttpClientFactory httpFactory,
        string baseClientServerUri,
        string baseIdentityServerUri,
        string identityScope,
        string identityClientId,
        string identityClientSecret,
        ILogger<BaseIdentityClientService> logger)
    {
        _httpFactory = httpFactory;
        _identityScope = identityScope;
        _identityClientId = identityClientId;
        _identityClientSecret = [REDACTED];
        _logger = logger;

        Client = _httpFactory.CreateClient("client");
        Client.BaseAddress = new Uri(baseClientServerUri);
        Client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));

        IdentityClient = _httpFactory.CreateClient("identity");
        IdentityClient.BaseAddress = new Uri(baseIdentityServerUri);
        IdentityClient.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
    }

    protected HttpClient Client { get; private set; }
    protected HttpClient IdentityClient { get; private set; }
    protected string? AccessToken { get; private set; }

    protected Task SendAsync(HttpMethod method, string path) =>
        SendAsync<object?>(method, path, null);

    /// <param name="serializerOptions">
    /// Options for serializing <paramref name="requestModel"/>. Defaults to the camelCase web
    /// conventions of <see cref="JsonContent"/>.
    /// </param>
    protected Task SendAsync<TRequest>(HttpMethod method, string path, TRequest requestModel,
        JsonSerializerOptions? serializerOptions = null) =>
        SendAsync<TRequest, object>(method, path, requestModel, false, serializerOptions);

    protected async Task<TResult?> SendAsync<TRequest, TResult>(HttpMethod method, string path,
        TRequest requestModel, bool hasJsonResult, JsonSerializerOptions? serializerOptions = null)
    {
        var fullRequestPath = string.Concat(Client.BaseAddress, path);

        var tokenStateResponse = await HandleTokenStateAsync();
        if (!tokenStateResponse)
        {
            _logger.LogError("Unable to send {Method} request to {RequestUri} because an access token was unable to be obtained",
                method.Method, fullRequestPath);
            return default;
        }

        // HandleTokenStateAsync should not return true when AccessToken is still null
        Debug.Assert(AccessToken is not null);

        var message = new TokenHttpRequestMessage(requestModel, AccessToken, serializerOptions)
        {
            Method = method,
            RequestUri = new Uri(fullRequestPath)
        };
        try
        {
            var response = await Client.SendAsync(message);
            if (response.IsSuccessStatusCode)
            {
                if (hasJsonResult)
                {
                    return await response.Content.ReadFromJsonAsync<TResult>();
                }
            }
            else
            {
                var errorResponse = await response.Content.ReadFromJsonAsync<ErrorResponse>();
                _logger.LogError("Request to {Url} is unsuccessful with status of {Code}-{Reason}: {Message}",
                    message.RequestUri.ToString(), response.StatusCode, response.ReasonPhrase, errorResponse);
            }
            return default;
        }
        catch (Exception e)
        {
            _logger.LogError(12334, e, "Failed to send to {0}.", message.RequestUri.ToString());
            return default;
        }
    }

    protected async Task<bool> HandleTokenStateAsync()
    {
        if (_nextAuthAttempt.HasValue && DateTime.UtcNow < _nextAuthAttempt.Value)
        {
            _logger.LogInformation("Not requesting a token at {now} because the next request time is {nextAttempt}", DateTime.UtcNow, _nextAuthAttempt.Value);
            return false;
        }
        _nextAuthAttempt = null;

        if (!string.IsNullOrWhiteSpace(AccessToken) && !TokenNeedsRefresh())
        {
            return true;
        }

        var requestMessage = new HttpRequestMessage
        {
            Method = HttpMethod.Post,
            RequestUri = new Uri(string.Concat(IdentityClient.BaseAddress, "connect/token")),
            Content = new FormUrlEncodedContent(new Dictionary<string, string>
            {
                { "grant_type", "client_credentials" },
                { "scope", _identityScope },
                { "client_id", _identityClientId },
                { "client_secret", _identityClientSecret }
            })
        };

        HttpResponseMessage? response = null;
        try
        {
            response = await IdentityClient.SendAsync(requestMessage);
        }
        catch (Exception e)
        {
            _logger.LogError(12339, e, "Unable to authenticate with identity server.");
        }

        if (response == null)
        {
            _logger.LogError("Empty token response from {identity} for client {clientId}", IdentityClient.BaseAddress, _identityClientId);
            return false;
        }

        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError("Unsuccessful token response from {identity} for client {clientId} with status {code}-{reason}", IdentityClient.BaseAddress, _identityClientId, response.StatusCode, response.ReasonPhrase);

            if (response.StatusCode == HttpStatusCode.BadRequest)
            {
                _nextAuthAttempt = DateTime.UtcNow.AddDays(1);
            }

            if (_logger.IsEnabled(LogLevel.Debug))
            {
                var responseBody = await response.Content.ReadAsStringAsync();
                _logger.LogDebug("Error response body:\n{ResponseBody}", responseBody);
            }

            return false;
        }

        var content = await response.Content.ReadAsStreamAsync();
        using var jsonDocument = await JsonDocument.ParseAsync(content);

        AccessToken = [REDACTED]"access_token").GetString();
        return true;
    }

    protected class TokenHttpRequestMessage : HttpRequestMessage
    {
        public TokenHttpRequestMessage(string token)
        {
            Headers.Add("Authorization", $"Bearer {token}");
        }

        public TokenHttpRequestMessage(
            object? requestObject, string token, JsonSerializerOptions? serializerOptions = null)
            : this(token)
        {
            if (requestObject != null)
            {
                Content = JsonContent.Create(requestObject, options: serializerOptions);
            }
        }
    }
    private class ErrorResponse
    {
        public string? Message { get; set; }
        public Dictionary<string, string[]>? ValidationErrors { get; set; }

        public override string ToString()
        {
            var sb = new StringBuilder();

            sb.AppendLine(Message ?? "Unknown error");

            if (ValidationErrors != null)
            {
                sb.AppendLine("Validation Errors:");

                foreach (var (key, value) in ValidationErrors)
                {
                    sb.Append(CultureInfo.InvariantCulture, $"{key}: ");
                    sb.AppendJoin(", ", value);
                    sb.AppendLine();
                }
            }

            return sb.ToString();
        }
    }

    protected bool TokenNeedsRefresh(int minutes = 5)
    {
        var decoded = DecodeToken();
        if (!decoded.RootElement.TryGetProperty("exp", out var expProp))
        {
            throw new InvalidOperationException("No exp in token.");
        }

        var expiration = CoreHelpers.FromEpocSeconds(expProp.GetInt64());
        return DateTime.UtcNow.AddMinutes(-1 * minutes) > expiration;
    }

    protected JsonDocument DecodeToken()
    {
        if (_decodedToken != null)
        {
            return _decodedToken;
        }

        if (AccessToken == null)
        {
            throw new InvalidOperationException($"{nameof(AccessToken)} not found.");
        }

        var parts = AccessToken.Split('.');
        if (parts.Length != 3)
        {
            throw new InvalidOperationException($"{nameof(AccessToken)} must have 3 parts");
        }

        var decodedBytes = CoreHelpers.Base64UrlDecode(parts[1]);
        if (decodedBytes == null || decodedBytes.Length < 1)
        {
            throw new InvalidOperationException($"{nameof(AccessToken)} must have 3 parts");
        }

        _decodedToken = [REDACTED];
        return _decodedToken;
    }

    public void Dispose()
    {
        _decodedToken?.Dispose();
    }
}

﻿using System.Linq.Expressions;
using AutoMapper;
using Bit.Core.Enums;
using Bit.Core.SecretsManager.Models.Data;
using Bit.Core.SecretsManager.Repositories;
using Bit.Infrastructure.EntityFramework.Repositories;
using Bit.Infrastructure.EntityFramework.SecretsManager.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

namespace Bit.Commercial.Infrastructure.EntityFramework.SecretsManager.Repositories;

public class ServiceAccountRepository : Repository<Core.SecretsManager.Entities.ServiceAccount, ServiceAccount, Guid>, IServiceAccountRepository
{
    public ServiceAccountRepository(IServiceScopeFactory serviceScopeFactory, IMapper mapper)
        : base(serviceScopeFactory, mapper, db => db.ServiceAccount)
    { }

    public async Task<IEnumerable<Core.SecretsManager.Entities.ServiceAccount>> GetManyByOrganizationIdAsync(Guid organizationId, Guid userId, AccessClientType accessType)
    {
        using var scope = ServiceScopeFactory.CreateScope();
        var dbContext = GetDatabaseContext(scope);
        var query = dbContext.ServiceAccount.Where(c => c.OrganizationId == organizationId);

        query = accessType switch
        {
            AccessClientType.NoAccessCheck => query,
            AccessClientType.User => query.Where(UserHasReadAccessToServiceAccount(userId)),
            _ => throw new ArgumentOutOfRangeException(nameof(accessType), accessType, null),
        };

        var serviceAccounts = await query.OrderBy(c => c.RevisionDate).ToListAsync();
        return Mapper.Map<List<Core.SecretsManager.Entities.ServiceAccount>>(serviceAccounts);
    }

    public async Task<IEnumerable<Core.SecretsManager.Entities.ServiceAccount>> GetManyByIds(IEnumerable<Guid> ids)
    {
        using var scope = ServiceScopeFactory.CreateScope();
        var dbContext = GetDatabaseContext(scope);
        var serviceAccounts = await dbContext.ServiceAccount
            .Where(c => ids.Contains(c.Id))
            .ToListAsync();
        return Mapper.Map<List<Core.SecretsManager.Entities.ServiceAccount>>(serviceAccounts);
    }

    public async Task<IEnumerable<Core.SecretsManager.Entities.ServiceAccount>> GetManyByOrganizationIdWriteAccessAsync(Guid organizationId, Guid userId, AccessClientType accessType)
    {
        using var scope = ServiceScopeFactory.CreateScope();
        var dbContext = GetDatabaseContext(scope);
        var query = dbContext.ServiceAccount.Where(c => c.OrganizationId == organizationId);

        query = accessType switch
        {
            AccessClientType.NoAccessCheck => query,
            AccessClientType.User => query.Where(UserHasWriteAccessToServiceAccount(userId)),
            _ => throw new ArgumentOutOfRangeException(nameof(accessType), accessType, null),
        };

        var serviceAccounts = await query.OrderBy(c => c.RevisionDate).ToListAsync();
        return Mapper.Map<List<Core.SecretsManager.Entities.ServiceAccount>>(serviceAccounts);
    }

    public async Task DeleteManyByIdAsync(IEnumerable<Guid> ids)
    {
        var targetIds = ids.ToList();
        using var scope = ServiceScopeFactory.CreateScope();
        var dbContext = GetDatabaseContext(scope);

        await using var transaction = await dbContext.Database.BeginTransactionAsync();

        // Policies can't have a cascade delete, so we need to delete them manually.
        await dbContext.AccessPolicies.Where(ap =>
                targetIds.Contains(((ServiceAccountProjectAccessPolicy)ap).ServiceAccountId!.Value) ||
                targetIds.Contains(((ServiceAccountSecretAccessPolicy)ap).ServiceAccountId!.Value) ||
                targetIds.Contains(((GroupServiceAccountAccessPolicy)ap).GrantedServiceAccountId!.Value) ||
                targetIds.Contains(((UserServiceAccountAccessPolicy)ap).GrantedServiceAccountId!.Value))
            .ExecuteDeleteAsync();

        await dbContext.ApiKeys
            .Where(a => targetIds.Contains(a.ServiceAccountId!.Value))
            .ExecuteDeleteAsync();

        await dbContext.ServiceAccount
            .Where(c => targetIds.Contains(c.Id))
            .ExecuteDeleteAsync();

        await transaction.CommitAsync();
    }

    public async Task<(bool Read, bool Write)> AccessToServiceAccountAsync(Guid id, Guid userId,
        AccessClientType accessType)
    {
        await using var scope = ServiceScopeFactory.CreateAsyncScope();
        var dbContext = GetDatabaseContext(scope);

        var serviceAccountQuery = dbContext.ServiceAccount.Where(sa => sa.Id == id);

        var accessQuery = BuildServiceAccountAccessQuery(serviceAccountQuery, userId, accessType);
        var access = await accessQuery.FirstOrDefaultAsync();

        return access == null ? (false, false) : (access.Read, access.Write);
    }

    public async Task<Dictionary<Guid, (bool Read, bool Write)>> AccessToServiceAccountsAsync(
        IEnumerable<Guid> ids,
        Guid userId,
        AccessClientType accessType)
    {
        await using var scope = ServiceScopeFactory.CreateAsyncScope();
        var dbContext = GetDatabaseContext(scope);

        var serviceAccountsQuery = dbContext.ServiceAccount.Where(p => ids.Contains(p.Id));
        var accessQuery = BuildServiceAccountAccessQuery(serviceAccountsQuery, userId, accessType);

        return await accessQuery.ToDictionaryAsync(access => access.Id, access => (access.Read, access.Write));
    }

    public async Task<int> GetServiceAccountCountByOrganizationIdAsync(Guid organizationId)
    {
        using (var scope = ServiceScopeFactory.CreateScope())
        {
            var dbContext = GetDatabaseContext(scope);
            return await dbContext.ServiceAccount
                .CountAsync(ou => ou.OrganizationId == organizationId);
        }
    }

    public async Task<int> GetServiceAccountCountByOrganizationIdAsync(Guid organizationId, Guid userId,
        AccessClientType accessType)
    {
        await using var scope = ServiceScopeFactory.CreateAsyncScope();
        var dbContext = GetDatabaseContext(scope);
        var query = dbContext.ServiceAccount.Where(sa => sa.OrganizationId == organizationId);

        query = accessType switch
        {
            AccessClientType.NoAccessCheck => query,
            AccessClientType.User => query.Where(UserHasReadAccessToServiceAccount(userId)),
            _ => throw new ArgumentOutOfRangeException(nameof(accessType), accessType, null),
        };

        return await query.CountAsync();
    }

    public async Task<ServiceAccountCounts> GetServiceAccountCountsByIdAsync(Guid serviceAccountId, Guid userId,
        AccessClientType accessType)
    {
        await using var scope = ServiceScopeFactory.CreateAsyncScope();
        var dbContext = GetDatabaseContext(scope);
        var query = dbContext.ServiceAccount.Where(sa => sa.Id == serviceAccountId);

        query = accessType switch
        {
            AccessClientType.NoAccessCheck => query,
            AccessClientType.User => query.Where(UserHasReadAccessToServiceAccount(userId)),
            _ => throw new ArgumentOutOfRangeException(nameof(accessType), accessType, null),
        };

        var serviceAccountCountsQuery = query.Select(serviceAccount => new ServiceAccountCounts
        {
            Projects = serviceAccount.ProjectAccessPolicies.Count,
            People = serviceAccount.UserAccessPolicies.Count + serviceAccount.GroupAccessPolicies.Count,
            AccessTokens = serviceAccount.ApiKeys.Count
        });

        var serviceAccountCounts = await serviceAccountCountsQuery.FirstOrDefaultAsync();
        return serviceAccountCounts ?? new ServiceAccountCounts { Projects = 0, People = 0, AccessTokens = 0 };
    }

    public async Task<bool> ServiceAccountsAreInOrganizationAsync(List<Guid> serviceAccountIds, Guid organizationId)
    {
        await using var scope = ServiceScopeFactory.CreateAsyncScope();
        var dbContext = GetDatabaseContext(scope);
        var result = await dbContext.ServiceAccount.CountAsync(sa =>
            sa.OrganizationId == organizationId && serviceAccountIds.Contains(sa.Id));
        return serviceAccountIds.Count == result;
    }

    public async Task<IEnumerable<ServiceAccountSecretsDetails>> GetManyByOrganizationIdWithSecretsDetailsAsync(
        Guid organizationId, Guid userId, AccessClientType accessType)
    {
        await using var scope = ServiceScopeFactory.CreateAsyncScope();
        var dbContext = GetDatabaseContext(scope);

        var serviceAccountQuery = dbContext.ServiceAccount.Where(c => c.OrganizationId == organizationId);
        serviceAccountQuery = accessType switch
        {
            AccessClientType.NoAccessCheck => serviceAccountQuery,
            AccessClientType.User => serviceAccountQuery.Where(c =>
                c.UserAccessPolicies.Any(ap => ap.OrganizationUser.User.Id == userId && ap.Read) ||
                c.GroupAccessPolicies.Any(ap =>
                    ap.Group.GroupUsers.Any(gu => gu.OrganizationUser.User.Id == userId && ap.Read))),
            _ => throw new ArgumentOutOfRangeException(nameof(accessType), accessType, null),
        };

        var projectSecretsAccessQuery = BuildProjectSecretsAccessQuery(dbContext, serviceAccountQuery);
        var directSecretAccessQuery = BuildDirectSecretAccessQuery(dbContext, serviceAccountQuery);

        var projectSecretsAccessResults = await projectSecretsAccessQuery.ToListAsync();
        var directSecretAccessResults = await directSecretAccessQuery.ToListAsync();

        var applicableDirectSecretAccessResults = FilterDirectSecretAccessResults(projectSecretsAccessResults, directSecretAccessResults);

        var results = projectSecretsAccessResults.Concat(applicableDirectSecretAccessResults)
            .GroupBy(g => g.ServiceAccount)
            .Select(g =>
                new ServiceAccountSecretsDetails
                {
                    ServiceAccount = Mapper.Map<Core.SecretsManager.Entities.ServiceAccount>(g.Key),
                    AccessToSecrets = g.Sum(x => x.SecretIds.Count())
                }).OrderBy(c => c.ServiceAccount.RevisionDate).ToList();

        return results;
    }

    private record ServiceAccountAccess(Guid Id, bool Read, bool Write);

    private static IQueryable<ServiceAccountAccess> BuildServiceAccountAccessQuery(IQueryable<ServiceAccount> serviceAccountQuery, Guid userId,
        AccessClientType accessType) =>
        accessType switch
        {
            AccessClientType.NoAccessCheck => serviceAccountQuery.Select(sa => new ServiceAccountAccess(sa.Id, true, true)),
            AccessClientType.User => serviceAccountQuery.Select(sa => new ServiceAccountAccess
            (
                sa.Id,
                sa.UserAccessPolicies.Any(ap => ap.OrganizationUser.User.Id == userId && ap.Read) ||
                sa.GroupAccessPolicies.Any(ap =>
                    ap.Group.GroupUsers.Any(gu => gu.OrganizationUser.User.Id == userId && ap.Read)),
                sa.UserAccessPolicies.Any(ap => ap.OrganizationUser.User.Id == userId && ap.Write) ||
                sa.GroupAccessPolicies.Any(ap =>
                    ap.Group.GroupUsers.Any(gu => gu.OrganizationUser.User.Id == userId && ap.Write))
            )),
            AccessClientType.ServiceAccount => serviceAccountQuery.Select(sa => new ServiceAccountAccess(sa.Id, false, false)),
            _ => serviceAccountQuery.Select(sa => new ServiceAccountAccess(sa.Id, false, false))
        };

    private static Expression<Func<ServiceAccount, bool>> UserHasReadAccessToServiceAccount(Guid userId) => sa =>
        sa.UserAccessPolicies.Any(ap => ap.OrganizationUser.User.Id == userId && ap.Read) ||
        sa.GroupAccessPolicies.Any(ap => ap.Group.GroupUsers.Any(gu => gu.OrganizationUser.User.Id == userId && ap.Read));

    private static Expression<Func<ServiceAccount, bool>> UserHasWriteAccessToServiceAccount(Guid userId) => sa =>
        sa.UserAccessPolicies.Any(ap => ap.OrganizationUser.User.Id == userId && ap.Write) ||
        sa.GroupAccessPolicies.Any(ap => ap.Group.GroupUsers.Any(gu => gu.OrganizationUser.User.Id == userId && ap.Write));

    private static IQueryable<ServiceAccountSecretsAccess> BuildProjectSecretsAccessQuery(DatabaseContext dbContext,
        IQueryable<ServiceAccount> serviceAccountQuery) =>
        from sa in serviceAccountQuery
        join ap in dbContext.ServiceAccountProjectAccessPolicy
            on sa.Id equals ap.ServiceAccountId into grouping
        from ap in grouping.DefaultIfEmpty()
        select new ServiceAccountSecretsAccess
        (
            sa, ap.GrantedProject.Secrets.Where(s => s.DeletedDate == null).Select(s => s.Id)
        );

    private static IQueryable<ServiceAccountSecretsAccess> BuildDirectSecretAccessQuery(
        DatabaseContext dbContext,
        IQueryable<ServiceAccount> serviceAccountQuery) =>
        from sa in serviceAccountQuery
        join ap in dbContext.ServiceAccountSecretAccessPolicy
            on sa.Id equals ap.ServiceAccountId into grouping
        from ap in grouping.DefaultIfEmpty()
        where ap.GrantedSecret.DeletedDate == null &&
              ap.GrantedSecretId != null
        select new ServiceAccountSecretsAccess(sa,
            new List<Guid> { ap.GrantedSecretId!.Value });

    private static List<ServiceAccountSecretsAccess> FilterDirectSecretAccessResults(
        List<ServiceAccountSecretsAccess> projectSecretsAccessResults,
        List<ServiceAccountSecretsAccess> directSecretAccessResults) =>
        directSecretAccessResults.Where(directSecretAccessResult =>
        {
            var serviceAccountId = directSecretAccessResult.ServiceAccount.Id;
            var secretId = directSecretAccessResult.SecretIds.FirstOrDefault();
            if (secretId == Guid.Empty)
            {
                return false;
            }

            return !projectSecretsAccessResults
                .Where(x => x.ServiceAccount.Id == serviceAccountId)
                .Any(x => x.SecretIds.Contains(secretId));
        }).ToList();

    private record ServiceAccountSecretsAccess(ServiceAccount ServiceAccount, IEnumerable<Guid> SecretIds);
}

﻿using Bit.Core.AdminConsole.OrganizationFeatures.Policies.PreAccess;
using Bit.Core.AdminConsole.Utilities.v2;
using Bit.Core.Entities;
using Bit.Core.Enums;

namespace Bit.Core.AdminConsole.OrganizationFeatures.Policies;

/// <summary>
/// Policy checks for a user joining an organization.
/// </summary>
/// <remarks>
/// The user's other organizations are checked via <see cref="IPolicyRequirementQuery"/>. The organization being joined
/// is checked via <see cref="IPreAccessPolicyEnforcer"/>, since the requirement framework doesn't cover new or Staged
/// members. Each check has an overload that loads its own data and one that takes preloaded data, for running several
/// checks at once.
/// </remarks>
public interface IJoinOrganizationPolicyValidationService
{
    /// <summary>
    /// Checks the Single Organization policy, both for the user's other organizations and the organization being joined.
    /// </summary>
    /// <param name="organizationId">The organization being joined.</param>
    /// <param name="user">The user joining.</param>
    /// <param name="proposedRole">The user's existing role, or <see cref="OrganizationUserType.User"/> if new.</param>
    /// <returns><c>null</c> if allowed, otherwise the error.</returns>
    /// <exception cref="PreAccessOrganizationNotFoundException">The organization does not exist.</exception>
    Task<Error?> ValidateSingleOrganizationPolicyAsync(Guid organizationId, User user, OrganizationUserType proposedRole);

    /// <inheritdoc cref="ValidateSingleOrganizationPolicyAsync(Guid, User, OrganizationUserType)" path="/summary|/param|/returns"/>
    /// <param name="policyEnforcer">The policy enforcer for the organization being joined.</param>
    /// <param name="allOrganizationMemberships">All of the user's organization memberships.</param>
    Task<Error?> ValidateSingleOrganizationPolicyAsync(Guid organizationId, User user, OrganizationUserType proposedRole,
        IPreAccessPolicyEnforcer policyEnforcer, ICollection<OrganizationUser> allOrganizationMemberships);

    /// <summary>
    /// Checks the Require Two-Factor Authentication policy of the organization being joined.
    /// </summary>
    /// <inheritdoc cref="ValidateSingleOrganizationPolicyAsync(Guid, User, OrganizationUserType)" path="/param|/returns|/exception"/>
    Task<Error?> ValidateTwoFactorAuthenticationPolicyAsync(Guid organizationId, User user,
        OrganizationUserType proposedRole);

    /// <inheritdoc cref="ValidateTwoFactorAuthenticationPolicyAsync(Guid, User, OrganizationUserType)" path="/summary|/param|/returns"/>
    /// <param name="policyEnforcer">The policy enforcer for the organization being joined.</param>
    Task<Error?> ValidateTwoFactorAuthenticationPolicyAsync(Guid organizationId, User user,
        OrganizationUserType proposedRole, IPreAccessPolicyEnforcer policyEnforcer);

    /// <summary>
    /// Checks the Automatic User Confirmation policy, both for the user's other organizations and the organization
    /// being joined.
    /// </summary>
    /// <inheritdoc cref="ValidateSingleOrganizationPolicyAsync(Guid, User, OrganizationUserType)" path="/param|/exception"/>
    Task<AutomaticUserConfirmationPolicyValidationResult> ValidateAutomaticUserConfirmationPolicyAsync(
        Guid organizationId, User user, OrganizationUserType proposedRole);

    /// <inheritdoc cref="ValidateAutomaticUserConfirmationPolicyAsync(Guid, User, OrganizationUserType)" path="/summary|/param"/>
    /// <param name="policyEnforcer">The policy enforcer for the organization being joined.</param>
    /// <param name="allOrganizationMemberships">All of the user's organization memberships.</param>
    Task<AutomaticUserConfirmationPolicyValidationResult> ValidateAutomaticUserConfirmationPolicyAsync(
        Guid organizationId, User user, OrganizationUserType proposedRole, IPreAccessPolicyEnforcer policyEnforcer,
        ICollection<OrganizationUser> allOrganizationMemberships);

    /// <summary>
    /// Checks the Account Recovery policy of the organization being joined.
    /// </summary>
    /// <inheritdoc cref="ValidateSingleOrganizationPolicyAsync(Guid, User, OrganizationUserType)" path="/param|/exception"/>
    /// <param name="resetPasswordKey">The user's reset password key, if any.</param>
    Task<AccountRecoveryPolicyValidationResult> ValidateAccountRecoveryPolicyAsync(Guid organizationId, User user,
        OrganizationUserType proposedRole, string? resetPasswordKey);

    /// <inheritdoc cref="ValidateAccountRecoveryPolicyAsync(Guid, User, OrganizationUserType, string?)" path="/summary|/param"/>
    /// <param name="policyEnforcer">The policy enforcer for the organization being joined.</param>
    AccountRecoveryPolicyValidationResult ValidateAccountRecoveryPolicy(Guid organizationId, User user,
        OrganizationUserType proposedRole, IPreAccessPolicyEnforcer policyEnforcer, string? resetPasswordKey);
}

